### 이진 탐색 C 구현 (반복문)

```c
#include <stdio.h>

// 정렬된 배열 list에서 key를 이진 탐색
int binary_search(int list[], int n, int key) {
    int low = 0;
    int high = n - 1;
    int mid;

    while (low <= high) {
        mid = (low + high) / 2;

        if (key == list[mid])
            return mid;          // 탐색 성공
        else if (key < list[mid])
            high = mid - 1;      // 왼쪽 절반으로
        else
            low = mid + 1;       // 오른쪽 절반으로
    }
    return -1;  // 탐색 실패
}

int main(void) {
    int list[] = {1, 3, 5, 7, 9, 11, 13};
    int n = 7;
    int key = 9;

    int result = binary_search(list, n, key);
    if (result >= 0)
        printf("탐색 성공: 인덱스 %d\n", result);
    else
        printf("탐색 실패\n");
    return 0;
}
// 출력: 탐색 성공: 인덱스 4
```

### 이진 탐색 트리 탐색 코드

```c
TreeNode* search(TreeNode* root, int key) {
    if (root == NULL || root->key == key)
        return root;
    if (key < root->key)
        return search(root->left, key);
    else
        return search(root->right, key);
}
